const login = $input.first().json;
let setCookie = (login.headers || {})['set-cookie'];
if (Array.isArray(setCookie)) setCookie = setCookie.join('; ');
const m = /tm_session=([^;]+)/.exec(setCookie || '');
if (!m) throw new Error('Giriş başarısız: tm_session çerezi alınamadı. TM_BOT_USERNAME / TM_BOT_PASSWORD değerlerini kontrol edin.');
const body = $('Webhook').first().json.body || {};
const canvasQuery = String(body.canvas || '').trim();
const prompt = String(body.prompt || '').trim();
if (!canvasQuery) throw new Error('İstek gövdesinde "canvas" alanı gerekli (kanvas adı veya id).');
if (!prompt) throw new Error('İstek gövdesinde "prompt" alanı gerekli.');
return [{ json: { cookie: 'tm_session=' + m[1], canvasQuery, prompt } }];

const prep = $('Hazırlık').first().json;
const canvases = $input.first().json.canvases || [];
const q = prep.canvasQuery.toLowerCase();
const canvas =
  canvases.find((c) => c.id === prep.canvasQuery) ||
  canvases.find((c) => c.name.toLowerCase() === q) ||
  canvases.find((c) => c.name.toLowerCase().includes(q));
if (!canvas) throw new Error('Kanvas bulunamadı: "' + prep.canvasQuery + '". Bot kullanıcının o kanvasa üye olduğundan emin olun (davet linkiyle ekleyin).');
return [{ json: { ...prep, canvasId: canvas.id, canvasName: canvas.name, role: canvas.role } }];

const found = $('Kanvası bul').first().json;
const state = $('Durum').first().json;
const regions = $input.first().json.regions || [];

const inRegion = (n, r) =>
  n.x != null && n.y != null &&
  n.x >= r.x && n.x <= r.x + r.width &&
  n.y >= r.y && n.y <= r.y + r.height;

const nodes = state.nodes.map((n) => ({
  id: n.id,
  parentId: n.parentId,
  title: n.title,
  description: (n.description || '').slice(0, 300),
  nodeType: n.nodeType,
  status: n.status,
  x: n.x,
  y: n.y,
  regions: regions.filter((r) => inRegion(n, r)).map((r) => r.name),
}));
const edges = state.edges.map((e) => ({
  id: e.id, sourceId: e.sourceId, targetId: e.targetId,
  kind: e.kind, direction: e.direction, label: e.label,
}));
const regionInfo = regions.map((r) => ({ id: r.id, name: r.name, x: r.x, y: r.y, width: r.width, height: r.height }));
const root = state.nodes.find((n) => n.parentId === null);

const system = [
  'Sen TreeMapper adlı iş birlikli planlama uygulaması için çalışan bir ajansın. Sana bir kanvasın güncel durumu (düğümler, kenarlar, bölgeler) ve kullanıcının doğal dildeki isteği verilir.',
  '',
  'YALNIZCA geçerli bir JSON nesnesi döndür (markdown, kod bloğu, ek metin YOK). İki mod var:',
  '1) Bilgi/özet isteği (\"özetle\", \"anlat\", \"listele\", \"durum ne\"): {\"mode\":\"summary\",\"reply\":\"<Türkçe yanıt>\"}',
  '2) Değişiklik/diyagram isteği (\"çiz\", \"ekle\", \"oluştur\", \"diyagramını yap\"): {\"mode\":\"diagram\",\"reply\":\"<yapılanın Türkçe özeti>\",\"message\":\"<kısa commit mesajı>\",\"ops\":[...]}',
  '',
  'ops dizisindeki geçerli işlemler (intent şemaları — alanlara birebir uy):',
  '- {\"op\":\"add_node\",\"id\":\"<benzersiz kısa id>\",\"title\":\"...\",\"parentId\":\"<mevcut düğüm id>\",\"description\":\"...\",\"nodeType\":\"task|idea|feature|milestone\",\"status\":\"planned|in_progress|done\",\"x\":<sayı>,\"y\":<sayı>}',
  '- {\"op\":\"add_edge\",\"sourceId\":\"...\",\"targetId\":\"...\",\"kind\":\"flow|loop|dependency|relation\",\"label\":\"...\",\"direction\":\"directed|bidirectional\"}',
  '- {\"op\":\"update_node\",\"id\":\"...\",\"fields\":{\"title\"?,\"description\"?,\"nodeType\"?,\"status\"?,\"parentId\"?}}',
  '- {\"op\":\"move_node\",\"id\":\"...\",\"x\":<sayı>,\"y\":<sayı>}',
  '- {\"op\":\"delete_node\",\"id\":\"...\"} ve {\"op\":\"delete_edge\",\"id\":\"...\"}',
  '',
  'KURALLAR:',
  '- Yeni düğümlere kendin id ver (ör. \"ai-a1\") ve kenarlarda bu id\'leri kullan; mevcut id\'lerle çakışmasın.',
  '- Yeni düğümlerde parentId olarak kullanıcı başka bir düğüm belirtmediyse kök düğümün id\'sini kullan.',
  '- Kullanıcı bir BÖLGE adı verdiyse yeni düğümlerin x/y koordinatlarını o bölgenin dikdörtgeni İÇİNE yerleştir (bir düğüm yaklaşık 220x100 birim yer kaplar; düğümleri en az 240 birim yatay / 130 birim dikey aralıkla ızgara gibi diz, dikdörtgen kenarlarından en az 20 birim içeride kalsın). Akış diyagramlarında akış yönünde sırala.',
  '- Bölge belirtilmediyse x/y VERME (null bırakılır, düğüm bölge dışı sayılır) ya da bölgelerin dışında bir koordinat seç.',
  '- Özet/analiz isteklerinde ASLA ops üretme; mode \"summary\" olsun.',
  '- Kullanıcı açıkça silme istemedikçe delete_node / delete_edge kullanma.',
  '- Kullanıcı bir bölgeden bahsediyorsa düğümlerin \"regions\" alanına bakarak o bölgedeki düğümleri esas al.',
  '- reply her zaman Türkçe, kısa ve net olsun.',
].join('\n');

const userText = [
  'Kanvas: ' + found.canvasName,
  'Kök düğüm id: ' + (root ? root.id : 'yok'),
  '',
  'BÖLGELER: ' + JSON.stringify(regionInfo),
  '',
  'DÜĞÜMLER: ' + JSON.stringify(nodes),
  '',
  'KENARLAR: ' + JSON.stringify(edges),
  '',
  'KULLANICI İSTEĞİ: ' + found.prompt,
].join('\n');

const geminiBody = {
  system_instruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: userText }] }],
  generationConfig: { temperature: 0.2, responseMimeType: 'application/json' },
};

return [{ json: { ...found, headSeq: state.headSeq, geminiBody } }];

const ctx = $('Bağlam').first().json;
const res = $input.first().json;
let text = (res.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
text = text.trim().replace(/^```(json)?\s*/i, '').replace(/```\s*$/, '').trim();
let out;
try {
  out = JSON.parse(text);
} catch {
  out = { mode: 'summary', reply: text || 'Modelden kullanılabilir bir yanıt alınamadı.' };
}
const allowed = new Set(['add_node', 'update_node', 'delete_node', 'move_node', 'add_edge', 'delete_edge']);
let ops = Array.isArray(out.ops) ? out.ops.filter((o) => o && allowed.has(o.op)) : [];
if (out.mode !== 'diagram') ops = [];
if (ops.length > 0 && ctx.role === 'viewer') {
  return [{ json: { hasOps: false, reply: 'Bot kullanıcı bu kanvasta "viewer" rolünde olduğu için değişiklik yapamıyorum. İstenen değişiklik: ' + String(out.reply || ''), cookie: ctx.cookie, canvasId: ctx.canvasId } }];
}
return [{ json: {
  cookie: ctx.cookie,
  canvasId: ctx.canvasId,
  headSeq: ctx.headSeq,
  reply: String(out.reply || ''),
  message: String(out.message || 'n8n ajan değişikliği'),
  ops,
  hasOps: ops.length > 0,
} }];

const parsed = $('Yanıtı çöz').first().json;
const outcome = $input.first().json;
if (outcome.result === 'committed') {
  return [{ json: { reply: parsed.reply, committed: true, commitSeq: outcome.commit.seq, opCount: parsed.ops.length } }];
}
if (outcome.result === 'branched') {
  return [{ json: {
    reply: parsed.reply + '\n\nNot: siz komut verirken kanvas değişip çakışma oluştuğu için değişiklikler "' + outcome.branch.name + '" dalına yazıldı. Kanvasta Dallar panelinden birleştirebilir veya iptal edebilirsiniz.',
    committed: false,
    branched: true,
    branch: outcome.branch.name,
  } }];
}
return [{ json: {
  reply: 'Değişiklik uygulanamadı: ' + (outcome.error || JSON.stringify(outcome)) + '\n\nPlanlanan değişiklik: ' + parsed.reply,
  committed: false,
  error: outcome.error || 'bilinmeyen hata',
} }];
